"""Cross-provider parity: the same golden transcripts must hold on every backend we route to."""
import pytest
from app.llm import complete_on

BACKENDS = ["bedrock", "openai"]

@pytest.mark.parametrize("backend", BACKENDS)
def test_golden_transcript_parity(backend, golden_transcripts):
    """Equivalence gate: every backend must agree on the golden set."""
    for case in golden_transcripts:
        out = complete_on(backend, case.prompt)
        assert case.assertion(out), f"cross-backend parity broke on {backend}"
